mapper.select:
select issue_id, project_id, provider, pr_number, fingerprint,
       first_task_id, first_run_id, last_task_id, last_run_id, issue_rank,
       severity, category, title, description, file_path, start_line, end_line,
       evidence, suggestion, origin, status, resolve_note, close_source,
       closed_by, closed_time, create_by, create_time, update_by, update_time
from review_issue
where project_id = #{projectId}
  and pr_number = #{prNumber}
  and fingerprint = #{fingerprint}
limit 1


where 1 = 1

    and i.project_id = #{projectId}


    and i.status = #{status}


    and i.severity = #{severity}


    and i.origin = #{origin}


    and i.pr_number = #{prNumber}


    and (i.title like concat('%', #{keyword}, '%') or i.file_path like concat('%', #{keyword}, '%'))


    and i.create_time >= #{beginTime}


    and i.create_time <= #{endTime}

${params.dataScope}
order by i.update_time desc, i.issue_id desc
